Using the frozen Brief and approved skeleton, write a complete ExperimentalMusicSpec. Preserve the skeleton's identity and section plan while realizing concrete notes, rests, velocities and useful CC. Output only the complete spec JSON.


FROZEN BRIEF:
{
  "id": "l1-song-hook",
  "level": "L1",
  "title": "Open-window song hook",
  "purpose": "An original eight-bar instrumental hook that could anchor an optimistic indie-pop song.",
  "duration_seconds": 18,
  "section_plan": [
    "hook: 8 bars"
  ],
  "style": [
    "indie pop",
    "clear diatonic harmony",
    "singable"
  ],
  "mood": [
    "hopeful",
    "open",
    "human"
  ],
  "must_include": [
    "four-bar harmonic question and answer",
    "recognizable two-bar melodic cell",
    "bass supports chord inversions"
  ],
  "must_avoid": [
    "quoted melodies",
    "constant eighth-note melody",
    "four identical bars"
  ],
  "instrument_roles": [
    "piano harmony",
    "lead melody",
    "bass"
  ],
  "delivery": [
    "8 bars",
    "3 tracks",
    "complete note endings"
  ],
  "score_focus": [
    "harmony",
    "melody",
    "brief match"
  ],
  "mode_a": true
}

SKELETON:
{
  "title": "Open-window song hook",
  "tempo_map": [
    {"bar": 1, "bpm": 107}
  ],
  "key_map": [
    {"bar": 1, "key": "G", "mode": "major"}
  ],
  "sections": [
    {"id": "hook", "start_bar": 1, "num_bars": 8, "time_signature": "4/4"}
  ],
  "track_plan": [
    {
      "id": "piano",
      "name": "Piano Harmony",
      "role": "harmony",
      "register": {"low": 48, "high": 84},
      "instrument_hint": "acoustic grand piano",
      "section_jobs": [
        {"section_id": "hook", "intent": "diatonic chords with rhythmic comping and sustained pads, supports inversions", "density": "medium"}
      ]
    },
    {
      "id": "melody",
      "name": "Lead Melody",
      "role": "melody",
      "register": {"low": 60, "high": 79},
      "instrument_hint": "warm lead synth or vocal-like instrument",
      "section_jobs": [
        {"section_id": "hook", "intent": "singable two-bar cell repeated with variation, rests between phrases", "density": "sparse"}
      ]
    },
    {
      "id": "bass",
      "name": "Bass",
      "role": "bass",
      "register": {"low": 28, "high": 55},
      "instrument_hint": "electric bass",
      "section_jobs": [
        {"section_id": "hook", "intent": "supports chord inversions with pedal tones and stepwise movement, sparse syncopation", "density": "sparse"}
      ]
    }
  ],
  "motif_strategy": "Lead melody uses a two-bar descending 3-note cell (e.g., D-C-B over G) with a rising counter-response in the second bar. The cell is restated in bars 5-6 with slight rhythmic variation and an answer phrase in bars 7-8 to create question/answer over the 8-bar hook.",
  "harmony_strategy": "Question bars 1-4: G (I) - D/F# (V6) - Em7 (vi7) - Cmaj7 (IVmaj7); Answer bars 5-8: G/B (I6) - D/F# (V6) - C (IV) - G (I). Bass notes follow inversions (F#, B, etc.) to create stepwise motion and clear harmonic direction.",
  "groove_strategy": "Piano provides offbeat eighth-note comping with occasional sustained chords; bass plays root/inversion notes on beats 1 and 3 with some passing tones; melody rhythm is primarily quarter and dotted half notes, avoiding constant eighth-note motion. Snare-like backbeat can be implied by piano chord stabs on beats 2 and 4."
}

